script:
(function () {
  'use strict';
  // How long savings last with an inflation-rising withdrawal. Annual steps: at the start of year
  // y (y = 0, 1, ...) you withdraw W(y) = spending x (1 + inflation)^y / (1 - tax rate) (tax only
  // for pre-tax accounts, so the after-tax amount you spend is "spending"), and the remaining
  // balance earns the annual return. When W(y) is larger than the balance the money runs out
  // part-way through that year: years lasted = y + balance / W(y). Runs are capped at 100 years.
  // CHECKS (Node, scratch tests): return = inflation (5%/5%) with $1,000,000 and $50,000 lasts
  // exactly 20 years (real return 0); 0% return and 0% inflation: $750,000 at $45,000 lasts
  // 16.67 years; with no inflation the result matches the annuity-due solution
  // n = -ln(1 - S x r / (W x (1 + r))) / ln(1 + r) (S = $500,000, W = $40,000, r = 6%: 21.1 years,
  // closed form 21.10); pre-tax 20% grosses $40,000 up to $50,000; a return high enough never to
  // deplete shows 100+ years; $0 savings, $0 spending and -20% returns give no NaN.
  var MAX_YEARS = 100;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var one = new Intl.NumberFormat('en-US', { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', minimumFractionDigits: 1, maximumFractionDigits: 1 });

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  // S savings, spend first-year after-tax spending, r return, inf inflation, tax (decimals).
  function run(S, spend, r, inf, tax) {
    var bal = S, rows = [], years = null, total = 0, growthTotal = 0, spentTotal = 0;
    for (var y = 0; y < MAX_YEARS; y++) {
      var need = spend * Math.pow(1 + inf, y), gross = need / (1 - tax);
      if (gross > bal + 1e-9) {
        years = y + (gross > 0 ? bal / gross : 0);
        rows.push({ year: y + 1, spend: need * (gross > 0 ? bal / gross : 0), out: bal, growth: 0, balance: 0 });
        total += bal; spentTotal += need * (gross > 0 ? bal / gross : 0); bal = 0;
        break;
      }
      bal -= gross;
      var growth = bal * r;
      bal += growth;
      if (bal < 0) bal = 0;
      total += gross; spentTotal += need; growthTotal += growth;
      rows.push({ year: y + 1, spend: need, out: gross, growth: growth, balance: bal });
    }
    return { years: years, rows: rows, total: total, growth: growthTotal, tax: total - spentTotal, end: bal };
  }

  function yearsText(y) { return y === null ? MAX_YEARS + '+' : one.format(y); }

  function update() {
    var S = num('hlSavings'), spend = num('hlSpend'), rate = num('hlRate'), inf = num('hlInflation'),
        age = num('hlAge'), pretax = document.getElementById('hlAccount').value === 'pretax',
        taxIn = num('hlTax');
    document.getElementById('hlWrapTax').hidden = !pretax;
    var tax = pretax ? taxIn : 0;
    var error = document.getElementById('hlError');
    var bad = [S, spend, rate, inf, age, tax].some(isNaN) || S < 0 || spend < 0 || rate < -20 || rate > 30 ||
              inf < 0 || inf > 20 || tax < 0 || tax > 60 || age < 18 || age > 100;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, a return from -20% to 30%, inflation from 0 to 20%, a tax rate from 0 to 60% and an age from 18 to 100.';
      return;
    }
    var r = rate / 100, i = inf / 100, t = tax / 100;
    var res = run(S, spend, r, i, t);
    var first = spend / (1 - t);
    set('hlLasts', res.years === null ? MAX_YEARS + '+ years' : one.format(res.years) + ' years');
    set('hlAgeOut', res.years === null ? 'Not within ' + MAX_YEARS + ' years' : 'Age ' + one.format(age + res.years));
    set('hlFirst', money.format(first));
    set('hlWdRate', S > 0 ? pct.format(first / S) : '–');
    set('hlTotal', money.format(res.total));
    set('hlGrowth', money.format(res.growth));
    set('hlTaxPaid', money.format(res.tax));
    var summary;
    if (spend === 0) summary = 'With no withdrawals your savings are never used up.';
    else if (S === 0) summary = 'With no savings, every withdrawal would have to come from other income.';
    else if (res.years === null) summary = 'Your savings still hold ' + money.format(res.end) + ' after ' + MAX_YEARS +
      ' years, so at this return they are unlikely to run out.';
    else summary = 'Spending ' + money.format(spend) + ' a year' + (inf > 0 ? ', rising ' + inf + '% a year with inflation,' : '') + ' uses up ' +
      money.format(S) + ' in about ' + one.format(res.years) + ' years, around age ' + Math.floor(age + res.years) + '.';
    set('hlSummary', summary);

    // Sensitivity grid: returns (rows) x first-year spending (columns).
    var mult = [0.8, 0.9, 1, 1.1, 1.2], deltas = [-2, -1, 0, 1, 2];
    document.getElementById('hlGridHead').innerHTML = '<th scope="col">Return</th>' + mult.map(function (m) {
      return '<th scope="col">' + money.format(spend * m) + '/yr</th>';
    }).join('');
    document.getElementById('hlGrid').innerHTML = deltas.map(function (d) {
      var rr = rate + d;
      return '<tr><th scope="row">' + one.format(rr) + '%</th>' + mult.map(function (m) {
        var cell = yearsText(run(S, spend * m, rr / 100, i, t).years);
        return '<td>' + (d === 0 && m === 1 ? '<strong>' + cell + '</strong>' : cell) + '</td>';
      }).join('') + '</tr>';
    }).join('');

    document.getElementById('hlSchedule').innerHTML = res.rows.map(function (row) {
      return '<tr><td>' + row.year + '</td><td>' + (Math.round(age) + row.year - 1) + '</td><td>' + money.format(row.spend) +
             '</td><td>' + money.format(row.out) + '</td><td>' + money.format(row.growth) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('hlForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
